    "Key": "AppSecurity",
    "ResourceKey": "AppSecurity",
    "Script": "RolePrivManagement = {
    init: async function(app, container, role) {
        app = app || session.app;
        container = container || $(".component[name=RolePrivManagement]");
        if(!role) { return; }
        api.addToMetaCache([{
            Name: "AppSecurity",
            Types: [
                [meta[Core/Privilege]],
                [meta[Core/Role]]
            ]
        }]);
        var privileges = await api.get("AppSecurity/Privilege?$orderby=Type asc,Operation asc");
        var rolePrivs = (role.Privs || "").split(",").map(function(priv) { return priv.trim(); }).filter(function(priv) { return priv.length > 0; });
        var data = (privileges.value || []).map(function(privilege) {
            privilege.Selected = rolePrivs.indexOf(privilege.Id) >= 0;
            return privilege;
        });
        var gridContainer = $("[name=privilegeGrid]", container);
        if(gridContainer.length === 0) { gridContainer = container; }
        var grid = new GridWidget(gridContainer, { data: data });
        grid.groupable = false;
        grid.filterable = true;
        grid.pageable = false;
        grid.editable = true;
        grid.toolbar = `<div class="btn-group btn-group-sm"><button class="btn btn-primary" name="savePrivs"><span class="k-icon k-i-save"></span>[resource_displayname[save]]</button></div>`;
        grid.columns = [
            { field: "Selected", title: " ", width: 80 },
            { field: "Type", title: "[resource_displayname[type]]", editable: false },
            { field: "Operation", title: "[resource_displayname[operation]]", editable: false },
            { field: "Description", title: "[resource_displayname[description]]", editable: false }
        ];
        await grid.init();
        $("[name=savePrivs]", grid.gridElement).off("click").on("click", async function(e) {
            e.preventDefault();
            var selected = grid.dataSource().data().filter(function(privilege) { return privilege.Selected === true; }).map(function(privilege) { return privilege.Id; });
            role.Privs = selected.join(",");
            await api.update("AppSecurity/Role(" + role.Id + ")", role).then(function() {
                notification.success("[resource_displayname[saved]]");
            }).catch(function(err) { error(err); });
        });
    }
